INSERT INTO episodes (slug, guid, date, title, explicit, language, source_url, session_started_at, session_ended_at, turn_count, transcript_path, transcript_sha256, transcript_bytes, summary, sync_offset_seconds, alignment_method, alignment_coverage, asr_model, recording_started_at, raw_audio_sha256, alignment_path, episode_number, tts_voice, recording_method, narrator_voice, ai_reconstructed, ai_disclosure, audio_key, audio_url, audio_bytes, audio_sha256, audio_mime, duration_seconds, loudness_lufs) VALUES ('eve-cant-find-andreessen', 'ask-eve:2026-10-23_eve-cant-find-andreessen', '2026-10-23', 'Eve Can''t Find the Andreessen Episode', 1, 'en', 'https://grok.com/share/c2hhcmQtMg_690b09f6-ae41-47b8-a260-b1e5ae045afe', '2026-10-23T18:20:39.000Z', '2026-10-23T18:28:09.000Z', 32, 'episodes/2026-10-23_eve-cant-find-andreessen.md', 'f3c71ef7778b6b57d132a3f997cb36b28222cb55f8dd915c94d4c00058a59f10', 10600, 'Episode 2 starts as a sound check on the new podcast and turns into a debugging session. David asks Eve what they talked about last time, and she recaps the setup work but not the long conversation about Marc Andreessen and Ben Horowitz. Her search comes up empty even when David gives her the exact title, until she reads the episode 0 transcript from the repo and then pulls the original chat through its Grok share link. The rest is Eve working out, out loud, why her memory missed it: two search systems that don''t talk to each other, and an index that may be stale or filtered. On the audio: David''s lines are his real voice from a phone recording, except three that were typed or came after the recording ended, which are left unvoiced. Eve''s lines are her text replies re-voiced with AI text-to-speech, and one reply that ends mid-sentence in the export is kept as is.', 4.62, 'asr-david-gaps', 0.9286, 'json-words', NULL, NULL, 'alignment/2026-10-23_eve-cant-find-andreessen.json', 2, 'xai_tts voice=eve', 'mic-plus-tts', 'xai_tts voice=rex', 1, 'AI-reconstructed audio: Eve''s lines are xAI text-to-speech (''eve'' voice) from the verbatim transcript; David''s lines are his own recorded voice where the recording matches the transcript. David''s lines with no matching recording are flagged as missing audio and are not voiced (no narrator fill). Transcript gaps are marked, not invented.', 'audio/en/2026-10-23_eve-cant-find-andreessen.v1.mp3', 'https://audio.askevepodcast.com/audio/en/2026-10-23_eve-cant-find-andreessen.v1.mp3', 7864270, '7f413ff45050b7544d44449a850d7947a504f5323011126deb2f9c5f20396803', 'audio/mpeg', 491, -16.9)
